.replaceAll(' ','')??'')==null?'Entrez un montant valide':null),const SizedBox(height:12),TextFormField(controller:startDate,decoration:const InputDecoration(labelText:'Date de début (JJ/MM/AAAA)')),const SizedBox(height:12),TextFormField(controller:endDate,decoration:const InputDecoration(labelText:'Date de fin (JJ/MM/AAAA)'))])))),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('Annuler')),FilledButton(onPressed:(){if(!keyForm.currentState!.validate())return;final value=double.tryParse(amount.text.replaceAll(' ',''))??0;Navigator.pop(context,Project(name:name.text.trim(),clientName:clientName,status:status,amount:value,startDate:startDate.text.trim(),endDate:endDate.text.trim()));},child:const Text('Enregistrer'))]);}
